"""Writing generated files: the GENERATED header and the one --check / write protocol.

Every generator computes `out`, a dict {Path: text} of the files it owns, and ends in main() with

    if '--check' in sys.argv:
        return writer.check(out, 'stale spec laws: ', 'spec laws are current', orphans=orphans)
    writer.write(out, orphans=orphans)

`check` prints what is stale and exits 1 (regenerate_all.py reads the exit code and the words stale/orphan in the
output); `write` removes the orphans (files the generator no longer produces) and writes every file.
"""
import re
import sys
from pathlib import Path
from typing import Iterable, Mapping

from codegen.core.repository_paths import ROOT

# The first words of every header: tools and the generators' own orphan scans recognise generated files by them.
PREFIX = '# GENERATED'
HEADER_RE = re.compile(r'# GENERATED (by \w+ \(codegen(: [^)]*)?\)|from [\w.]+ by \w+ \(codegen\))')


def header(generator: str, detail: str = '', *, tail: str = '. Do not edit.') -> str:
    """The header line of a file `generator` writes: `# GENERATED by <generator> (codegen[: detail]). Do not edit.`
    `generator` is the file stem (names are unique across codegen/): the line does not change when the file moves."""
    return f'{PREFIX} by {generator} (codegen' + (f': {detail}' if detail else '') + f'){tail}'


_OWNER_RE = re.compile(r'# GENERATED by (?:codegen/(?:\w+/)*)?(\w+)(?:\.py| \(codegen)')


def owner(text: str) -> 'str | None':
    """The generator (file stem) a generated file's header names, from its first 8000 characters; None when it has no
    header. Reads the pre-layout form `# GENERATED by codegen/<dir>/<name>.py` too."""
    m = _OWNER_RE.search(text[:8000])
    return m.group(1) if m else None


def is_foreign(path: Path, me: str) -> bool:
    """whether `path` is a generated file another generator than `me` wrote (a generator's orphan scan must skip those:
    several generators write into the same glob)"""
    o = owner(path.read_text())
    return o is not None and o != me


def rebrand(text: str, old: str, new: str, detail: str = '') -> str:
    """`text` as written by generator `old`, now written by `new`: the header line and the generator path mentions
    (`codegen/<dir>/old.py`, same directory) name `new`; `detail` goes after `new` in the header's parenthesis."""
    text = text.replace(f'by {old} (codegen)', f'by {new} (codegen' + (f': {detail}' if detail else '') + ')')
    return re.sub(rf'(codegen/(?:\w+/)*){old}\.py', rf'\g<1>{new}.py', text)


def rel(path: Path) -> str:
    return str(path.relative_to(ROOT))


def stale(out: Mapping[Path, str]) -> list:
    """repo-relative names of the files of `out` that are missing or differ from their text"""
    return [rel(p) for p, t in out.items() if not p.exists() or p.read_text() != t]


def check(out: Mapping[Path, str], stale_msg: str, ok_msg: str, orphans: Iterable[str] = ()) -> None:
    """--check: print `stale_msg` + the names and exit 1 when a file of `out` is stale or an orphan remains;
    otherwise print `ok_msg`."""
    bad = stale(out) + list(orphans)
    if bad:
        print(stale_msg + ', '.join(bad))
        sys.exit(1)
    print(ok_msg)


def write(out: Mapping[Path, str], orphans: Iterable[str] = ()) -> None:
    """write mode: delete the orphans (repo-relative names), then write every file of `out`"""
    for q in orphans:
        (ROOT / q).unlink()
    for p, t in out.items():
        p.write_text(t)
